callGraph.callee:
zones.map(z => {
          const v = z.verdict || '—';
          const vClass = v === 'PAY' ? 'verdict-pay'
            : v === 'POSSIBLE' ? 'verdict-possible'
            : v === 'NON_PAY' ? 'verdict-nonpay'
            : 'verdict-unknown';
          return `<div class="wd-zone-row ${vClass}">
            <span class="wd-zone-depth">${z.top}–${z.bot} m</span>
            <span class="wd-zone-verdict">${v}</span>
          </div>`;
        }).join
